// Interface - capability
public interface ILogger {
    void Log(string message);
}

// Abstract class - base behavior
public abstract class LoggerBase : ILogger {
    public void Log(string message) {
        WriteToLog(Format(message));
    }
    protected abstract void WriteToLog(string message);
    protected virtual string Format(string msg) => $"[{DateTime.Now}] {msg}";
}

// Modern: default interface method
public interface IModernLogger {
    void Log(string message);
    void LogError(string message) => Log($"ERROR: {message}");
}
